/** Root-only read-only stage observation. Importing performs no I/O. */
import { open, realpath } from "node:fs/promises"
import { dirname, resolve } from "node:path"
import { connectOperator } from "../tools/staging/m73-common"
import { readMigrationManifest } from "../packages/neuvetra-database/src/staging-migrations"
import { parseM80Json } from "../packages/neuvetra-database/src/m80-validation"
import { captureApplicationState, check, exactKeys, hash, sha } from "./m80-backup-core"
import { helperPins } from "./m80-backup-hosted-entry"
import type { WorkspaceConnection, WorkspaceSql } from "../packages/neuvetra-database/src/workspace"

export const ACCEPTED_BACKUP_HELPER = "429ac122e20aec4230300ef092d9534a7cd912ec39ee65d2c6e33f8b040faf07"
export async function observeStageDatabase(db: WorkspaceConnection, schema: 21 | 22, capture = captureApplicationState) {
  const manifest = await readMigrationManifest()
  check(manifest.length === 22, "Exact current manifest required.")
  return db.transaction(async (tx: WorkspaceSql) => {
    await tx.exec("set transaction isolation level repeatable read read only")
    const target = (await tx.query<{database: string; actor: string; readOnly: string}>("select current_database() database,current_user actor,current_setting('transaction_read_only') \"readOnly\"")).rows
    check(target.length === 1 && target[0]!.database === "postgres" && target[0]!.actor === "postgres" && target[0]!.readOnly === "on", "Exact read-only operator target required.")
    const profile = (await tx.query<{projectRef: string; profile: string}>("select project_ref \"projectRef\",profile from neuvetra.staging_target")).rows
    check(profile.length === 1 && profile[0]!.projectRef === "icockcoguyadhryzydvl" && profile[0]!.profile === "neuvetra.private-synthetic-staging.v1", "Fixed synthetic project required.")
    const sessions = (await tx.query<{count: number}>("select count(*)::int count from pg_stat_activity where datname=current_database() and usename='neuvetra_runtime' and backend_type='client backend'")).rows
    check(sessions.length === 1 && sessions[0]!.count === 0, "Zero runtime sessions required.")
    const state = await capture(tx)
    check(hash(state.migrationReceipts) === hash(manifest.slice(0, schema).map(({name, sha256}) => ({name, sha256}))), "Exact requested migration receipts required.")
    return { profile: "neuvetra.m80.stopped-database-observation.v1", observedAt: new Date().toISOString(), projectRef: "icockcoguyadhryzydvl", currentSchemaVersion: schema, currentMigrationReceiptCount: state.migrationReceipts.length, currentApplicationStateSha256: state.applicationStateSha256, observedNonReceiptTableCount: state.observedNonReceiptTables.length, activeRuntimeSessionCount: 0, noActiveApplicationWritesObserved: true, readOnly: true }
  })
}

export async function runStageObserver(input: unknown) {
  exactKeys(input, ["operatorId", "operatorDatabaseUrl", "schemaVersion", "outputPath"], "Closed stage observer input required.")
  const value = input as {operatorId: string; operatorDatabaseUrl: string; schemaVersion: 21 | 22; outputPath: string}
  check(value.operatorId === "/root" && typeof value.operatorDatabaseUrl === "string" && [21, 22].includes(value.schemaVersion) && typeof value.outputPath === "string", "Exact root stage observer input required.")
  const pins = await helperPins()
  check(pins.helperSha256 === ACCEPTED_BACKUP_HELPER, "Accepted complete backup source closure changed.")
  const path = resolve(value.outputPath), parent = await realpath(resolve(".superpowers"))
  check(dirname(path) === parent && /^m80-stage-observation-[a-z0-9-]+\.json$/.test(path.slice(parent.length + 1)), "Fixed private observation path required.")
  check(!await Bun.file(path).exists(), "Existing observation refused.")
  const db = await connectOperator(value.operatorDatabaseUrl)
  let receipt: Awaited<ReturnType<typeof observeStageDatabase>>
  try { receipt = await observeStageDatabase(db, value.schemaVersion) } finally { await db.close() }
  const bytes = JSON.stringify({...receipt, acceptedBackupHelperSha256: pins.helperSha256}, null, 2) + "\n"
  const file = await open(path, "wx", 0o600)
  try { await file.writeFile(bytes); await file.sync() } finally { await file.close() }
  return {status: "m80_stage_readonly_observation_passed", schemaVersion: value.schemaVersion, receiptSha256: sha(bytes)}
}
if (import.meta.main) {
  try {
    const text = await Bun.stdin.text(); check(Buffer.byteLength(text) <= 8192, "Stage observer input too large.")
    console.log(JSON.stringify(await runStageObserver(parseM80Json(text))))
  } catch { console.error('{"status":"m80_stage_readonly_observation_refused"}'); process.exitCode = 1 }
}

import { expect, test } from "bun:test"
import { observeStageDatabase } from "./m80-stage-observe"
import { readMigrationManifest } from "../packages/neuvetra-database/src/staging-migrations"
import type { WorkspaceConnection } from "../packages/neuvetra-database/src/workspace"

async function fixture(schema: 21 | 22, overrides: Record<string, unknown> = {}) {
 const commands: string[] = []
 const tx = {
  exec: async (sql: string) => { commands.push(sql) },
  query: async (sql: string) => {
   commands.push(sql)
   if (sql.includes("current_database() database")) return {rows: [{database:"postgres",actor:"postgres",readOnly:"on",...overrides.target as object}]}
   if (sql.includes("staging_target")) return {rows: [{projectRef:"icockcoguyadhryzydvl",profile:"neuvetra.private-synthetic-staging.v1",...overrides.profile as object}]}
   if (sql.includes("pg_stat_activity")) return {rows: [{count: overrides.sessions ?? 0}]}
   throw Error("Unexpected SQL")
  },
 }
 const db = {transaction: async (fn: (value: typeof tx) => Promise<unknown>) => fn(tx)} as unknown as WorkspaceConnection
 const migrationReceipts = (await readMigrationManifest()).slice(0,schema).map(({name,sha256})=>({name,sha256}))
 if (overrides.corruptReceipt) migrationReceipts[0]!.sha256="0".repeat(64)
 const capture = async () => ({migrationReceipts,applicationStateSha256:"a".repeat(64),observedNonReceiptTables:["neuvetra.example"]}) as any
 return {db,capture,commands}
}
test("schema21 and22 observation uses a read-only transaction and exact receipts",async()=>{
 for (const schema of [21,22] as const) {
  const f=await fixture(schema);const result=await observeStageDatabase(f.db,schema,f.capture)
  expect(f.commands[0]).toBe("set transaction isolation level repeatable read read only")
  expect(f.commands.slice(1).every(sql=>sql.startsWith("select "))).toBe(true)
  expect(result.currentSchemaVersion).toBe(schema);expect(result.currentMigrationReceiptCount).toBe(schema)
  expect(result.readOnly).toBe(true);expect(result.activeRuntimeSessionCount).toBe(0)
 }
})
test("wrong targets, writable transactions, active sessions and corrupt receipts refuse",async()=>{
 for (const overrides of [{target:{database:"foreign"}},{target:{actor:"other"}},{target:{readOnly:"off"}},{profile:{projectRef:"foreign"}},{profile:{profile:"other"}},{sessions:1},{sessions:"0"},{corruptReceipt:true}]) {
  const f=await fixture(22,overrides);await expect(observeStageDatabase(f.db,22,f.capture)).rejects.toThrow()
 }
})

#requires -Version 7.0
param(
 [Parameter(Mandatory=$true)][string]$ExportPath,
 [Parameter(Mandatory=$true)][ValidateSet(21,22)][int]$SchemaVersion,
 [Parameter(Mandatory=$true)][string]$OutputPath
)
$ErrorActionPreference='Stop'
try {
 $expectedPwsh='C:\Users\nimab\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\pwsh.exe'
 $currentPwsh=[IO.Path]::GetFullPath((Get-Process -Id $PID).Path)
 if(-not $currentPwsh.Equals($expectedPwsh,[StringComparison]::OrdinalIgnoreCase) -or (Get-FileHash -Algorithm SHA256 -LiteralPath $currentPwsh).Hash.ToLowerInvariant() -ne '362a356ce7f0940ec74f73a8fc2c990a2cc24a38a11c90bbd8eca947110ad139'){throw 'exact reviewed runtime required'}
 $values=@()
 foreach($line in [IO.File]::ReadAllLines([IO.Path]::GetFullPath($ExportPath))){
  if($line -match '^\s*(?:export\s+)?DATABASE_URL\s*=\s*(.*?)\s*$'){
   $value=$Matches[1]
   if($value.StartsWith('"')){$value=ConvertFrom-Json $value}
   elseif($value.StartsWith("'") -and $value.EndsWith("'")){$value=$value.Substring(1,$value.Length-2)}
   $values+=$value
  }elseif($line -match '^\s*"DATABASE_URL"\s*:\s*("(?:[^"\\]|\\.)*")\s*,?\s*$'){$values+=(ConvertFrom-Json $Matches[1])}
 }
 if($values.Count -ne 1){throw 'exact DATABASE_URL required'}
 $uri=[Uri]$values[0];$user=$uri.UserInfo.Split(':',2)
 if($uri.Scheme -notin @('postgres','postgresql') -or $uri.Host -ne 'aws-1-us-west-1.pooler.supabase.com' -or $uri.Port -ne 5432 -or $uri.AbsolutePath -ne '/postgres' -or [Uri]::UnescapeDataString($user[0]) -ne 'postgres.icockcoguyadhryzydvl' -or $user.Count -ne 2 -or -not $user[1]){throw 'fixed database target required'}
 $payload=[ordered]@{operatorId='/root';operatorDatabaseUrl=$values[0];schemaVersion=$SchemaVersion;outputPath=[IO.Path]::GetFullPath($OutputPath)}
 $start=[Diagnostics.ProcessStartInfo]::new();$start.FileName=(Get-Command bun).Source;$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
 $start.ArgumentList.Add('run');$start.ArgumentList.Add([IO.Path]::GetFullPath('.superpowers/m80-stage-observe.ts'))
 $process=[Diagnostics.Process]::Start($start);$stdout=$process.StandardOutput.ReadToEndAsync();$stderr=$process.StandardError.ReadToEndAsync()
 $process.StandardInput.Write(($payload|ConvertTo-Json -Compress));$process.StandardInput.Close();$process.WaitForExit()
 if($process.ExitCode -ne 0){throw 'read-only stage observer refused'}
 [Console]::Out.Write($stdout.Result)
}catch{
 [Console]::Out.Write('{"status":"m80_stage_readonly_bridge_refused"}')
 exit 1
}
